import React, { useCallback, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_LIVEBOARD_ID, TOP_HEADER_PX } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const BST_BLUE = '#1D3FA8';
const DASHBOARD_EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 220px)`;

interface ViewChip {
  id: string;
  label: string;
  activeTabId: string;
}

const VIEW_CHIPS: ViewChip[] = [
  { id: 'overview',     label: 'Overview',                activeTabId: '4cae1a0e-1887-4ffa-8058-891010ca0701' },
  { id: 'performance',  label: 'Performance & Ranking',   activeTabId: 'b05e15ee-aff3-4609-ae4c-46db06b28ac6' },
  { id: 'time',         label: 'Time Development',        activeTabId: 'c19dfa82-ba9d-4136-9317-eb941558f081' },
  { id: 'quality',      label: 'Quality & Failures',      activeTabId: 'a4164f3d-9f06-4aa3-9725-3e179efc474f' },
  { id: 'geography',    label: 'Geography & Customers',   activeTabId: '8701338d-ab38-428e-8752-0c27e3462b3e' },
];

export default function DashboardHome() {
  const { hiddenActions, disabledActions, tier } = useTier();
  const [selectedView, setSelectedView] = useState('overview');

  const selected = VIEW_CHIPS.find(v => v.id === selectedView)!;

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Liveboard Dashboard]', formatThoughtSpotEmbedError(err), err);
  }, []);

  return (
    <div style={{ backgroundColor: BST_BLUE }}>

      {/* Blue header banner */}
      <div style={{ padding: '1.75rem 2.5rem 1.25rem', backgroundColor: BST_BLUE }}>
        <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.55)', marginBottom: 6 }}>BST Media</div>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: '#ffffff', margin: 0 }}>Logi Liveboard</h1>
        <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.75)', margin: '6px 0 0', maxWidth: 640 }}>
          Welcome to BST Media Analytics. You are on the{' '}
          <strong style={{ color: '#ffffff' }}>{tier}</strong> access level — change it in the sidebar to see different embed capabilities.
        </p>
      </div>

      {/* Native filter chips — view switcher */}
      <div style={{ padding: '0 2.5rem 1.25rem', display: 'flex', gap: 8, flexWrap: 'wrap' }}>
        {VIEW_CHIPS.map(chip => {
          const isActive = chip.id === selectedView;
          return (
            <button
              key={chip.id}
              type="button"
              onClick={() => setSelectedView(chip.id)}
              style={{
                padding: '7px 16px',
                borderRadius: 20,
                border: `1px solid ${isActive ? '#ffffff' : 'rgba(255,255,255,0.35)'}`,
                background: isActive ? '#ffffff' : 'rgba(255,255,255,0.1)',
                color: isActive ? BST_BLUE : 'rgba(255,255,255,0.85)',
                fontSize: 13,
                fontWeight: isActive ? 700 : 500,
                cursor: 'pointer',
                transition: 'all 0.15s ease',
                whiteSpace: 'nowrap',
              }}
            >
              {chip.label}
            </button>
          );
        })}
      </div>

      {/* Embed card */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div
          style={{
            backgroundColor: '#ffffff',
            borderRadius: 12,
            border: 'none',
            minHeight: DASHBOARD_EMBED_MIN_H,
            overflow: 'visible',
          }}
        >
          <LiveboardEmbed
            key={selectedView}
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            activeTabId={selected.activeTabId}
            fullHeight
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            isLiveboardCompactHeaderEnabled
            hideTabPanel
            isLiveboardStylingAndGroupingEnabled
            onError={onError}
            style={{ width: '100%', minHeight: DASHBOARD_EMBED_MIN_H, display: 'block', border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
